mapper.select:
/*selectMasterMdAmLogManageList*/ SELECT A.LOG_SEQ ,DECODE(A.SYSTEM, 'KOREAB2B', '구매대행MRO', 'CMRO', '건설MRO', 'KWAY', '유통', A.SYSTEM) AS SYSTEM ,A.MENU ,A.LOG_TYPE ,TO_CHAR(SUBSTR(A.ATTR_01,0,3000)) ATTR_01 ,A.ATTR_02 ,A.ATTR_03 ,A.REG_IP ,A.REG_NM ,TO_CHAR(ADD_DATE,'YYYY-MM-DD HH24:MI') AS ADD_DATE FROM KEPSITE_LOG A WHERE 1=1
AND TO_CHAR(ADD_DATE,'YYYYMMDDHH24MI') BETWEEN #{st_from_date}||#{st_from_time1}||#{st_from_time2} AND #{st_to_date}||#{st_to_time1}||#{st_to_time2}
AND A.SYSTEM = #{st_system}
AND A.REG_NM LIKE '%' || #{st_add_name} || '%'
AND A.REG_IP LIKE '%' || #{st_add_ip} || '%'
AND A.MENU IN (SELECT CODE2 FROM ICOMCOD3 WHERE TYPE = 'LOG_TYPE' AND BUYER = 'KRKORE0001' AND CODE1 = #{st_menu})
UNION ALL SELECT A.LOG_SEQ ,DECODE(A.SYSTEM, 'KOREAB2B', '구매대행MRO', 'CMRO', '건설MRO', 'KWAY', '유통', A.SYSTEM) AS SYSTEM ,A.MENU ,A.LOG_TYPE ,TO_CHAR(SUBSTR(A.ATTR_01,0,3000)) ATTR_01 ,A.ATTR_02 ,A.ATTR_03 ,A.REG_IP ,A.REG_NM ,TO_CHAR(ADD_DATE,'YYYY-MM-DD HH24:MI') AS ADD_DATE FROM KEPCON.KEPSITE_LOG@KEPCON A WHERE 1=1
AND TO_CHAR(ADD_DATE,'YYYYMMDDHH24MI') BETWEEN #{st_from_date}||#{st_from_time1}||#{st_from_time2} AND #{st_to_date}||#{st_to_time1}||#{st_to_time2}
AND A.SYSTEM = #{st_system}
AND A.REG_NM LIKE '%' || #{st_add_name} || '%'
AND A.REG_IP LIKE '%' || #{st_add_ip} || '%'
ORDER BY SYSTEM,ADD_DATE DESC
